'use strict';
const $=id=>document.getElementById(id),asset=s=>`assets/${s}.png`;
const categories=[{name:'Трофеи',icon:'s6_7',color:'#ba8876'},{name:'Растения',icon:'s7_0',color:'#abc279'},{name:'Руда',icon:'s8_4',color:'#8db6cd'},{name:'Снаряжение',icon:'s9_0',color:'#d5c2a0'}];
const raw=[['Коготь зверя',0,'s6_7'],['Пучок перьев',0,'s6_4'],['Клык вожака',0,'s6_5'],['Чешуя ящера',0,'s6_14'],['Череп зверя',0,'s6_10'],['Крыло мотылька',0,'s6_12'],['Красный гриб',1,'s7_0'],['Лунный гриб',1,'s7_1'],['Лечебный лист',1,'s7_2'],['Морозный цветок',1,'s7_3'],['Сухой корень',1,'s7_5'],['Солнечный цвет',1,'s7_6'],['Уголь',2,'s8_0'],['Серебряная руда',2,'s8_1'],['Золотая руда',2,'s8_2'],['Аметист',2,'s8_3'],['Ледяной кристалл',2,'s8_4'],['Кристальная жеода',2,'s8_5'],['Железный меч',3,'s9_0'],['Кинжал',3,'s9_1'],['Топор',3,'s9_2'],['Копьё',3,'s9_3'],['Охотничий лук',3,'s9_4'],['Арбалет',3,'s9_5'],['Шлем',3,'s9_6'],['Красный щит',3,'s9_7'],['Латная перчатка',3,'s9_8'],['Сапоги',3,'s9_9'],['Кольчуга',3,'s9_10'],['Верёвка',3,'s9_14']];
const items=raw.map(([name,cat,sprite],id)=>({id,name,cat,sprite}));
const adventurers=[['Роуэн','лесной разведчик','s3_0','Из Сумрачного леса. Грибы, трофеи и немного полезного железа. Разложишь?'],['Бран','страж перевала','s3_1','На перевале завалило старую шахту. Спас всё, что смог. В мешке вперемешку!'],['Торн','охотник на чудовищ','s3_2','Хорошая была охота! Только осторожнее с когтями — очень острые.'],['Мирра','лесная собирательница','s3_3','Принесла дары леса и находки у старых руин. Наведём здесь порядок?'],['Финн','искатель сокровищ','s3_5','Говорят, у тебя ни одна вещь не теряется. Проверим? Вот моя добыча.'],['Огри','добродушный великан','s3_6','Огри нашёл много хорошего. Огри всё положил в один мешок. Тебе работа!'],['Клёп','болотный старатель','s3_7','Всё честно добыто! Почти всё чистое. Найдёшь для этого место?']];
const customers=[['Эльмир','алхимик гильдии','s4_0'],['Хальд','городской кузнец','s4_1'],['Лира','хранительница записей','s4_5'],['Тавен','хозяин таверны','s4_3']];
let state={day:1,seconds:300,started:false,paused:false,screen:'reception',mode:'sort',gold:0,rep:0,stock:[],bag:null,visitor:null,order:null,activeCat:null,inspectCat:null,menuCat:null,selectedItem:null,combo:0,errors:0,dayErrors:0,daySorted:0,dayGold:0,dayVisitors:0,dayOrders:0,arrivals:0,nextArrival:0,closing:false,ended:false,selectedBag:false,autoSorting:false,muted:true};
let adTimer=null,adToken=0,adReady=false,itemDepth=1000,uid=0,toastTimer,scale=1,drag=null,suppressClick=false,audioCtx=null,last=performance.now();
function rand(a,b){return Math.floor(a+Math.random()*(b-a+1))}function choose(a){return a[rand(0,a.length-1)]}function entry(type){return {uid:++uid,type}}function totalStock(cat){return state.stock.filter(x=>items[x.type].cat===cat).length}function currentVisitor(){return adventurers[state.visitor??0]}
function resize(){scale=Math.min(innerWidth/1280,innerHeight/800);$('game').style.transform=`scale(${scale})`;const v=$('viewport');v.style.width='100vw'}addEventListener('resize',resize);resize();
function beep(kind='good'){if(state.muted)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const t=audioCtx.currentTime;const play=(f,dt,d,v,type='sine')=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.setValueAtTime(f,t+dt);g.gain.setValueAtTime(v,t+dt);g.gain.exponentialRampToValueAtTime(.001,t+dt+d);o.connect(g);g.connect(audioCtx.destination);o.start(t+dt);o.stop(t+dt+d)};if(kind==='bad'){play(125,0,.15,.08,'triangle');play(96,.06,.16,.05)}else if(kind==='coin'){[523,659,784,1046].forEach((f,i)=>play(f,i*.055,.22,.07))}else if(kind==='box'){play(135,0,.12,.08,'triangle');play(190,.03,.12,.05)}else{play(440+Math.min(state.combo,8)*45,0,.09,.06,'triangle');play(750,.025,.1,.035)}}catch{}}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2800)}
function modal(html,locked=false){if(state.autoSorting)return;cancelAdPreview();cancelDrag();$('modal').classList.remove('order-brief');$('modalContent').innerHTML=html;$('modal').classList.remove('hidden');$('closeModal').classList.toggle('hidden',locked);state.paused=true;updateHud()}
function closeModal(){if(state.ended)return;cancelAdPreview();$('modal').classList.add('hidden');$('modal').classList.remove('order-brief');state.paused=false;last=performance.now();updateHud()}
function fly(sprite,from,to){let im=document.createElement('img');im.src=asset(sprite);im.className='flying';const r=$('game').getBoundingClientRect();let x=(from.left+from.width/2-r.left)/scale-38,y=(from.top+from.height/2-r.top)/scale-38;im.style.left=x+'px';im.style.top=y+'px';$('effects').append(im);requestAnimationFrame(()=>{im.style.left=(to.left+to.width/2-r.left)/scale-38+'px';im.style.top=(to.top+to.height/2-r.top)/scale-38+'px';im.style.transform='scale(.3) rotate(15deg)';im.style.opacity='.2'});setTimeout(()=>im.remove(),310)}
function reward(n){let d=document.createElement('div');d.className='reward';d.textContent=`+${n} золота`;d.style.left='850px';d.style.top='270px';$('effects').append(d);setTimeout(()=>d.remove(),1100)}
function pay(n,r){state.gold+=n;state.dayGold+=n;state.rep+=r;beep('coin');reward(n);updateHud()}
function updateHud(){const hour=8+(1-state.seconds/300)*12;const hh=Math.min(20,Math.floor(hour)),mm=Math.floor((hour-hh)*60);$('dayLabel').textContent=`День ${state.day}`;$('clock').textContent=state.closing?'20:00 · закрываемся':`${String(hh).padStart(2,'0')}:${String(mm).padStart(2,'0')} · ${state.paused?'пауза':hh<12?'утро':hh<17?'день':'вечер'}`;$('sunbar').style.width=state.seconds/3+'%';$('gold').textContent=state.gold;$('rep').textContent=state.rep;$('orderBadge').textContent=state.order?'1':'0';$('pause').textContent=state.paused?'▶':'Ⅱ';$('sound').textContent=state.muted?'♫̸':'♫';$('sound').setAttribute('aria-label',state.muted?'Включить звук':'Выключить звук')}
function setScreen(screen){if(state.autoSorting)return;cancelDrag();state.inspectCat=null;state.menuCat=null;state.selectedItem=null;state.activeCat=null;$('inspector').classList.add('hidden');$('boxMenu').classList.add('hidden');state.screen=screen;$('reception').classList.toggle('hidden',screen!=='reception');$('work').classList.toggle('hidden',screen!=='work');$('tooltip').style.display='none';render()}
function render(){updateHud();state.screen==='reception'?renderReception():renderWork()}
function renderReception(){const v=currentVisitor();$('visitor').classList.toggle('hidden',!state.bag&&!state.order);$('bag').classList.toggle('hidden',!state.bag);$('parcel').classList.toggle('hidden',!!state.bag||!state.order);$('receptionAction').innerHTML='';$('speech').classList.remove('hidden');let buttonText,action;
 if(!state.started){$('visitor').classList.remove('hidden');$('speech').innerHTML='<span class="eyebrow">ПЕРВАЯ СМЕНА</span><h2>Доброе утро, кладовщик!</h2><p>Герои уже возвращаются в город. Откроем склад?</p>';buttonText='Начать смену';action=startDay;$('notice').innerHTML='<b>Маленький склад у таверны</b><br>4 коробки · 1 стол · ваша первая смена';}
 else if(state.bag){$('visitor').src=asset(v[2]);$('speech').innerHTML=`<span class="eyebrow">${v[1]}</span><h2>${v[0]}</h2><p>${v[3]}</p>`;$('notice').innerHTML=`<b>Приём добычи</b><br>${state.bag.length} предметов ждут сортировки. ${state.closing?'Закончите этот мешок — смена завершится.':'Нажмите на мешок, чтобы развязать его.'}`;if(state.selectedBag){buttonText='Сортировать мешок';action=()=>{state.mode='sort';setScreen('work');beep('box')};}else if(state.bagOpened){buttonText='Продолжить сортировку';action=()=>{state.mode='sort';setScreen('work')}}}
 else if(state.order){$('speech').classList.add('hidden');const c=customers[state.order.customer];$('visitor').src=asset(c[2]);$('speech').innerHTML=`<span class="eyebrow">${c[1]}</span><h2>${c[0]}</h2><p>Собери, пожалуйста, несколько вещей из запасов. За точный заказ — <b>${state.order.reward} золота</b>.</p>`;buttonText='Посмотреть задание';action=openOrder;$('notice').innerHTML=`<b>Поручение гильдии</b><br>${state.order.recipe.map(r=>`${items[r.type].name} ×${r.count}`).join(' · ')}`;}
 else{$('speech').innerHTML='<span class="eyebrow">СКЛАД ОТКРЫТ</span><h2>Тихая минута</h2><p>Можно передохнуть. Следующий авантюрист уже в пути.</p>';const wait=Math.max(0,Math.ceil(state.nextArrival-(300-state.seconds)));$('notice').innerHTML=`<b>На полках: ${state.stock.length} предметов</b><br>Следующий посетитель ожидается примерно через <span id="waitSeconds">${wait}</span> сек.`;buttonText='Подождать у окна';action=waitAtWindow;}
 if(buttonText){let b=document.createElement('button');b.className='primary';b.textContent=buttonText;b.onclick=action;$('receptionAction').append(b)}
 $('stepHint').textContent=!state.started?'Смена длится 5 минут. Количество посетителей зависит от времени.':state.bag?'Мешок → стол → коробки на полках → оплата':state.order?'Теперь воспользуйтесь порядком, который создали на складе.':'Посетители приходят в разное время. Можно ускорить ожидание.';
}
function startDay(){if(state.started)return;state.started=true;state.nextArrival=0;arrive();render()}
function arrive(){if(state.closing||state.bag||state.order||state.screen!=='reception')return;state.visitor=state.arrivals%adventurers.length;state.arrivals++;state.dayVisitors++;state.combo=0;state.errors=0;state.selectedBag=false;state.bagOpened=false;let count=state.arrivals===1?15:rand(18,24);let pool=state.arrivals===1?[0,1,6,7,12,16,18,24]:items.map(x=>x.id);state.bag=Array.from({length:count},(_,i)=>({...entry(i<4?[0,6,12,18][i]:choose(pool)),bagSlot:i}));state.bagTotal=count;state.nextArrival=(300-state.seconds)+rand(35,105);render();beep('box')}
function tickArrival(){if(state.seconds<=0){state.seconds=0;state.closing=true;maybeEnd();return}if(300-state.seconds+1e-7>=state.nextArrival&&!state.bag&&!state.order&&state.screen==='reception')arrive()}
function updateWaitingNotice(){if(state.bag||state.order||state.screen!=='reception')return;const text=$('waitSeconds');if(text)text.textContent=Math.max(0,Math.ceil(state.nextArrival-(300-state.seconds)))}
function waitAtWindow(){if(!state.started||state.paused||state.ended||state.bag||state.order||state.screen!=='reception')return;if(state.closing||state.seconds<=0){tickArrival();return}const gap=Math.max(0,state.nextArrival-(300-state.seconds));if(gap>=state.seconds){state.seconds=0;tickArrival();return}state.seconds=Math.max(0,state.seconds-gap);arrive();updateHud()}
function maybeEnd(){if(state.closing&&!state.bag&&!state.order&&!state.ended)endDay()}
function shelfNode(cat){return $('shelves').querySelector(`[data-cat="${cat}"]`)}
function renderShelves(){const s=$('shelves');s.innerHTML='';categories.forEach((c,i)=>{const b=document.createElement('button');b.className='shelf-box'+(state.activeCat===i?' selected':'');b.dataset.cat=i;b.setAttribute('aria-label',`${c.name}: ${totalStock(i)} предметов. ${state.mode==='sort'?'Осмотреть или положить предмет':'Открыть коробку'}`);b.innerHTML=`<img class="boxart" src="${asset('s5_0')}" alt=""><img class="category-icon" src="${asset(c.icon)}" alt=""><span class="quantity">${totalStock(i)}</span><span class="tag">${c.name}</span>`;b.onclick=()=>selectBox(i);s.append(b)});['Артефакты','VIP-хранилище'].forEach(name=>{const b=document.createElement('button');b.className='shelf-box locked';b.innerHTML=`<img class="boxart" src="${asset('s5_4')}" alt=""><span class="quantity">🔒</span><span class="tag">${name}</span>`;b.onclick=()=>locked(name);s.append(b)})}
function selectBox(cat){if(state.autoSorting||state.paused||state.inspectCat!==null)return;if(state.mode==='sort'){if(state.selectedItem!==null){const node=$('pile').querySelector(`[data-uid="${state.selectedItem}"]`);putItem(state.selectedItem,node?.getBoundingClientRect(),cat);return}state.menuCat=state.menuCat===cat?null:cat;renderBoxMenu();return}if(state.activeCat!==null){toast('Закройте открытую коробку красным крестиком');return}state.activeCat=cat;state.selectedItem=null;beep('box');renderWork();$('sourceBox').classList.add('box-arriving');setTimeout(()=>$('sourceBox').classList.remove('box-arriving'),300)}
function renderBoxMenu(){const m=$('boxMenu');m.classList.toggle('hidden',state.menuCat===null);if(state.menuCat===null)return;const c=categories[state.menuCat];m.innerHTML=`<b>${c.name}</b><span>${totalStock(state.menuCat)} предметов</span><button id="inspectButton">Осмотреть</button><button id="dismissBoxMenu" aria-label="Закрыть меню">×</button>`;m.style.left=(113+state.menuCat*175)+'px';$('inspectButton').onclick=()=>openInspection(state.menuCat);$('dismissBoxMenu').onclick=()=>{state.menuCat=null;renderBoxMenu()}}
function openInspection(cat){if(state.autoSorting)return;if(!Number.isInteger(cat)||!categories[cat]||state.mode!=='sort')return;state.inspectCat=cat;state.menuCat=null;state.selectedItem=null;renderBoxMenu();$('inspectTitle').textContent=`${categories[cat].name} · ${totalStock(cat)} предметов`;$('inspector').classList.remove('hidden');$('tooltip').style.display='none';const list=state.stock.filter(x=>items[x.type].cat===cat);const area=$('inspectItems');area.innerHTML='';renderLooseItems(area,list,'inspect');if(!list.length)area.innerHTML='<div class="empty-pile">Коробка пока пуста<small>Перетащите в неё подходящие предметы со стола.</small></div>';$('inspectScroll').scrollTop=0;beep('box');$('closeInspector').focus()}
function closeInspection(){cancelDrag();const cat=state.inspectCat;state.inspectCat=null;$('inspector').classList.add('hidden');$('tooltip').style.display='none';renderPile();if(cat!==null)shelfNode(cat)?.focus()}
function returnBox(){if(state.activeCat===null)return;cancelDrag();const cat=state.activeCat,from=$('sourceBox').getBoundingClientRect();state.activeCat=null;state.selectedItem=null;beep('box');renderWork();const to=shelfNode(cat);if(to)fly('s5_0',from,to.getBoundingClientRect());if(orderComplete())toast('Посылка собрана! Нажмите «Выдать посылку» справа.')}
function renderWork(){const sort=state.mode==='sort';state.bagOpened=sort?true:state.bagOpened;$('work').classList.toggle('sorting',sort);$('work').classList.toggle('fulfillment',!sort);renderShelves();renderBoxMenu();$('workMode').textContent=sort?'ПРИЁМ И СОРТИРОВКА':'ПОРУЧЕНИЕ ГИЛЬДИИ';$('workTitle').textContent=sort?'Отправляйте добычу прямо на полки':'Соберите посылку по чек-листу';$('workProgress').textContent=sort?`${state.bagTotal-(state.bag?.length||0)} / ${state.bagTotal} разобрано`:`${state.order?.packed.length||0} / ${state.order?.recipe.reduce((s,r)=>s+r.count,0)||0} собрано`;$('pileCaption').textContent=sort?'ДОБЫЧА НА СТОЛЕ':'КОМПЛЕКТАЦИЯ ПОСЫЛКИ';$('combo').textContent=state.combo>=3?`${state.combo} подряд · отлично!`:'';$('stepHint').textContent=sort?'Предмет → коробка на полке. Нажмите коробку, чтобы осмотреть.':'Коробка на полке → нужные предметы в посылку → закрыть коробку';$('workHint').textContent=sort?'Собирайте кучки на столе · перетаскивайте предметы в коробки на полках':'Раздвигайте предметы внутри коробки · нужное перетащите в посылку слева';renderPile();renderBox();renderChecklist();renderSortActions();}
function renderPile(){const p=$('pile');p.innerHTML='';if(state.mode!=='sort')return;renderLooseItems(p,state.bag||[],'sort')}
function renderLooseItems(area,list,kind){const inspect=kind==='inspect',sort=kind==='sort';const width=area.clientWidth||420,size=sort?88:78;let maxY=inspect?280:200;list.forEach((x,i)=>{const slot=sort?(x.bagSlot??i):(x.slot??i),seed=(x.uid*931+7)%997;const it=items[x.type],b=document.createElement('button');b.className='item'+(state.selectedItem===x.uid?' chosen':'');b.dataset.uid=x.uid;b.dataset.kind=kind;b.setAttribute('aria-label',`${it.name}, ${categories[it.cat].name}${sort?'':', можно перемещать внутри коробки'}`);b.innerHTML=`<img draggable="false" src="${asset(it.sprite)}" alt="${it.name}">`;let left,top;if(sort){const w=area.clientWidth||1160,h=area.clientHeight||285,dx=Math.max(1,w-116),dy=Math.max(1,h-116);if(!x.tablePos)x.tablePos={x:Math.max(0,Math.min(1,((slot%11)*99+(seed%25)-14)/dx)),y:Math.max(0,Math.min(1,(Math.floor(slot/11)*90+(seed%19)-12)/dy))};left=14+x.tablePos.x*dx;top=14+x.tablePos.y*dy}else{if(!x.boxPos)x.boxPos={x:Math.min(1,Math.max(0,((slot%5)*79+(seed%23))/342)),y:Math.max(0,Math.floor(slot/5)*77+(seed%17))};left=x.boxPos.x*Math.max(1,width-size);top=x.boxPos.y;maxY=Math.max(maxY,top+size+10)}b.style.left=left+'px';b.style.top=top+'px';b.style.transform=`rotate(${seed%37-18}deg)`;b.style.zIndex=x.depth||slot+1;b.onpointerdown=e=>pointerDown(e,x,b,kind);b.onclick=()=>{if(suppressClick)return;if(inspect){toast(`${it.name} · перетащите, чтобы передвинуть`);return}if(sort){state.selectedItem=state.selectedItem===x.uid?null:x.uid;state.menuCat=null;renderPile();renderBoxMenu();if(state.selectedItem!==null)toast('Теперь нажмите на коробку на полке')}else putItem(x.uid,b.getBoundingClientRect())};b.onpointerenter=()=>showItemTip(b,it);b.onfocus=()=>showItemTip(b,it);b.onpointerleave=b.onblur=()=>$('tooltip').style.display='none';area.append(b)});if(!sort)area.style.height=maxY+'px'}
function showItemTip(b,it){if(drag)return;const t=$('tooltip');t.innerHTML=`${it.name}<br><small>${categories[it.cat].name}</small>`;const r=b.getBoundingClientRect(),g=$('game').getBoundingClientRect();t.style.left=Math.min(1020,Math.max(12,(r.left-g.left)/scale))+'px';t.style.top=Math.max(92,(r.top-g.top)/scale-58)+'px';t.style.display='block'}
function renderBox(){const z=$('boxZone'),source=$('sourceBox');z.innerHTML='';source.innerHTML='';source.classList.add('hidden');if(state.mode==='sort')return;z.innerHTML=`<div class="parcel-title">ПОСЫЛКА</div><div id="parcelDrop" role="region" aria-label="Посылка, положите сюда нужные предметы"><div id="packedItems"></div><span class="parcel-empty">${state.order?.packed.length?'':'Перетащите сюда<br>вещи из коробки'}</span></div><span class="parcel-count">${state.order?.packed.length||0} предметов в посылке</span>`;state.order?.packed.forEach((x,i)=>{let im=document.createElement('img');im.src=asset(items[x.type].sprite);im.alt=items[x.type].name;im.title=items[x.type].name;im.style.left=14+(i%3)*57+'px';im.style.top=12+Math.floor(i/3)*47+'px';im.style.transform=`rotate(${x.uid%21-10}deg)`;$('packedItems').append(im)});if(state.activeCat===null){source.classList.remove('hidden');source.className='source-placeholder';source.innerHTML='<div>Выберите коробку на полке<small>Откройте её, найдите нужную вещь<br>и положите в посылку слева.</small></div>';return}source.className='source-open';source.innerHTML=`<div class="source-heading"><div><b>${categories[state.activeCat].name}</b><span>${totalStock(state.activeCat)} предметов · вид сверху</span></div><button id="closeSource" class="red-close" aria-label="Закрыть коробку и вернуть на полку">×</button></div><div id="sourceScroll"><div id="sourceItems"></div></div>`;$('closeSource').onclick=returnBox;const list=state.stock.filter(x=>items[x.type].cat===state.activeCat);renderLooseItems($('sourceItems'),list,'source');if(!list.length)$('sourceItems').innerHTML='<div class="empty-pile">В коробке пусто</div>'}
function renderChecklist(){const c=$('checklist');c.classList.toggle('hidden',state.mode!=='order');if(state.mode!=='order'||!state.order){c.innerHTML='';return}const complete=orderComplete();c.innerHTML='<h3>Положить в посылку</h3>'+state.order.recipe.map(r=>{const n=state.order.packed.filter(x=>x.type===r.type).length,done=n===r.count;return `<div class="check-row ${done?'done':''}"><span class="checkmark">${done?'✓':'○'}</span><img src="${asset(items[r.type].sprite)}" alt=""><span class="check-name">${items[r.type].name}</span><b>${n}/${r.count}</b></div>`}).join('')+`<div class="dispatch-status">${complete?(state.activeCat!==null?'Всё собрано. Закройте коробку красным крестиком.':'Посылка собрана! Можно выдавать.'):`Награда: ${state.order.reward} золота`}</div>`+(complete&&state.activeCat===null?'<button class="primary" id="ship">Выдать посылку</button>':'');if(complete&&state.activeCat===null)$('ship').onclick=finishOrder}
function pointerDown(e,x,b,kind='sort'){if(state.autoSorting)return;if(e.button!==0||state.paused||(state.inspectCat!==null&&kind!=='inspect'))return;state.menuCat=null;renderBoxMenu();const r=b.getBoundingClientRect();drag={uid:x.uid,node:b,kind,startX:e.clientX,startY:e.clientY,rect:r,grabX:(e.clientX-r.left)/scale,grabY:(e.clientY-r.top)/scale,active:false,pointerId:e.pointerId};b.setPointerCapture(e.pointerId)}
function moveOnTable(d,x,y){if(d.kind!=='sort'||state.mode!=='sort'||state.screen!=='work'||state.paused||state.inspectCat!==null)return false;const area=$('pile'),table=$('table');if(!inside(table.getBoundingClientRect(),x,y))return false;const item=state.bag?.find(i=>i.uid===d.uid);if(!item)return false;const r=area.getBoundingClientRect(),dx=Math.max(1,(area.clientWidth||1160)-116),dy=Math.max(1,(area.clientHeight||285)-116);const left=Math.max(0,Math.min(dx,(x-r.left)/scale-d.grabX-14)),top=Math.max(0,Math.min(dy,(y-r.top)/scale-d.grabY-14));item.tablePos={x:left/dx,y:top/dy};item.depth=++itemDepth;state.selectedItem=null;d.node.classList.remove('chosen');d.node.style.left=14+left+'px';d.node.style.top=14+top+'px';d.node.style.zIndex=item.depth;return true}
function moveInsideBox(d,x,y){const inspect=d.kind==='inspect';if(d.kind!=='source'&&!inspect)return false;const pane=$(inspect?'inspectScroll':'sourceScroll'),area=$(inspect?'inspectItems':'sourceItems');if(!pane||!area||!inside(pane.getBoundingClientRect(),x,y))return false;const item=state.stock.find(i=>i.uid===d.uid),cat=inspect?state.inspectCat:state.activeCat;if(!item||items[item.type].cat!==cat)return false;const r=area.getBoundingClientRect(),width=area.clientWidth||420,height=Math.max(area.clientHeight||parseFloat(area.style.height)||200,pane.clientHeight||200);const usableX=Math.max(1,width-78),left=Math.min(usableX,Math.max(0,(x-r.left)/scale-d.grabX)),top=Math.min(Math.max(0,height-78),Math.max(0,(y-r.top)/scale-d.grabY));item.boxPos={x:left/usableX,y:top};item.depth=++itemDepth;d.node.style.left=left+'px';d.node.style.top=top+'px';d.node.style.zIndex=item.depth;beep('box');return true}
function inside(r,x,y){return x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom}
function dropTargetAt(x,y){if(state.paused||state.screen!=='work'||state.inspectCat!==null)return null;if(state.mode==='sort'){for(const b of $('shelves').querySelectorAll('[data-cat]'))if(inside(b.getBoundingClientRect(),x,y))return {node:b,cat:Number(b.dataset.cat)};return null}const p=$('parcelDrop');return p&&inside(p.getBoundingClientRect(),x,y)?{node:p,cat:null}:null}
function clearDropHighlights(){document.querySelectorAll('.drop-ready').forEach(n=>n.classList.remove('drop-ready'))}
function cancelDrag(){if(drag){drag.ghost?.remove();drag.node.style.opacity='';drag=null}clearDropHighlights()}
addEventListener('pointermove',e=>{if(!drag)return;if(!drag.active&&Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)<5)return;if(!drag.active){drag.active=true;drag.ghost=drag.node.cloneNode(true);drag.ghost.className='item dragging';drag.ghost.style.transform='none';const size=drag.kind==='sort'?88:78;drag.ghost.style.width=size*scale+'px';drag.ghost.style.height=size*scale+'px';document.body.append(drag.ghost);drag.node.style.opacity='.2';$('tooltip').style.display='none'}drag.ghost.style.left=e.clientX-drag.grabX*scale+'px';drag.ghost.style.top=e.clientY-drag.grabY*scale+'px';clearDropHighlights();if(drag.kind!=='inspect')dropTargetAt(e.clientX,e.clientY)?.node.classList.add('drop-ready');if(drag.kind!=='sort'){const pane=$(drag.kind==='inspect'?'inspectScroll':'sourceScroll');if(pane){const r=pane.getBoundingClientRect();if(inside(r,e.clientX,e.clientY)){if(e.clientY>r.bottom-28*scale)pane.scrollTop+=10;else if(e.clientY<r.top+28*scale)pane.scrollTop-=10}}}});
addEventListener('pointerup',e=>{if(!drag)return;const d=drag,target=d.kind==='inspect'?null:dropTargetAt(e.clientX,e.clientY);drag=null;clearDropHighlights();if(d.active){d.ghost.remove();d.node.style.opacity='';suppressClick=true;setTimeout(()=>suppressClick=false,80);if(state.paused)return;if(target)putItem(d.uid,{left:e.clientX,top:e.clientY,width:0,height:0},target.cat);else if(!moveOnTable(d,e.clientX,e.clientY)&&!moveInsideBox(d,e.clientX,e.clientY))toast(d.kind==='sort'?'Предмет остался на столе. Перемещайте его по столу или отправьте в коробку на полке':'Предмет остаётся в коробке. Перемещайте внутри её границ.')}});
addEventListener('pointercancel',cancelDrag);
function wrong(text,node){state.combo=0;state.errors++;state.dayErrors++;toast(text);beep('bad');if(node){node.classList.add('shake');setTimeout(()=>node.classList.remove('shake'),270)}$('combo').textContent=''}
function nextFreeSlot(cat){const used=new Set(state.stock.filter(x=>items[x.type].cat===cat).map(x=>x.slot));let slot=0;while(used.has(slot))slot++;return slot}
function putItem(id,from,targetCat=null,automated=false){if(state.autoSorting&&!automated)return;if(state.paused||state.screen!=='work'||state.inspectCat!==null)return;const sort=state.mode==='sort',list=sort?state.bag:state.stock;const idx=list?.findIndex(x=>x.uid===id);if(idx==null||idx<0)return;const x=list[idx],it=items[x.type];let target;if(sort){if(!Number.isInteger(targetCat)||!categories[targetCat])return;target=shelfNode(targetCat);if(it.cat!==targetCat){wrong(`«${it.name}» — ${categories[it.cat].name.toLowerCase()}. Предмет остался на столе.`,target);return}x.slot=nextFreeSlot(it.cat);list.splice(idx,1);state.stock.push(x);state.daySorted++;state.combo++;state.selectedItem=null;state.menuCat=null;}else{if(state.activeCat===null||it.cat!==state.activeCat)return;target=$('parcelDrop');const r=state.order?.recipe.find(r=>r.type===x.type);if(!r||state.order.packed.filter(a=>a.type===x.type).length>=r.count){wrong('Этот предмет не нужен — он остаётся в коробке',target);return}list.splice(idx,1);state.order.packed.push(x);state.combo++}if(from&&target)fly(it.sprite,from,target.getBoundingClientRect());beep();$('tooltip').style.display='none';const scroll=$('sourceScroll')?.scrollTop||0;renderWork();if(!sort&&$('sourceScroll'))$('sourceScroll').scrollTop=scroll;if(sort&&state.bag.length===0){finishBag();return}if(!sort&&orderComplete())toast('Всё собрано! Закройте коробку красным крестиком.');}

function finishBag(){if(!state.bag||state.bag.length)return;state.selectedItem=null;state.menuCat=null;const base=state.bagTotal*2,bonus=state.errors===0?10:0;state.bag=null;state.selectedBag=false;state.activeCat=null;state.dayBags=(state.dayBags||0)+1;pay(base+bonus,bonus?3:1);createOrder();renderWork();updateHud();toast(`Мешок принят: +${base} золота${bonus?' и +10 за аккуратность':''}. Заказчик ждёт у стойки.`)}
function returnToReception(){if(state.autoSorting)return;setScreen('reception');if(state.order&&!state.order.introSeen)introduceOrder()}
function renderSortActions(){const sorting=state.mode==='sort',done=sorting&&!state.bag&&!!state.order;$('autoSortButton').classList.toggle('hidden',!sorting);$('autoSortButton').disabled=state.autoSorting||!state.bag?.length;$('sortingDone').classList.toggle('hidden',!done);$('game').classList.toggle('auto-sorting',state.autoSorting);if(done){$('workTitle').textContent='Мешок разобран — наведите порядок';$('stepHint').textContent='Заказчик ждёт. Можно осмотреть коробки и разложить вещи удобнее.'}}
function cancelAdPreview(){adToken++;if(adTimer!==null)clearTimeout(adTimer);adTimer=null;adReady=false;$('modal').classList.remove('ad-preview')}
function showAutoSortAd(){if(state.autoSorting||state.screen!=='work'||state.mode!=='sort'||!state.bag?.length)return;if(state.inspectCat!==null)closeInspection();modal('<div class="brief-eyebrow">АВТОСОРТИРОВКА ЗА РЕКЛАМУ</div><h2>Просмотр рекламы</h2><p>Тестовый просмотр · 2 секунды</p><div class="ad-progress"><i></i></div><p id="adStatus">Дождитесь окончания просмотра…</p><button class="primary" id="confirmAutoSort" disabled>Отсортировать всё автоматически</button>');$('modal').classList.add('ad-preview');const token=adToken;adTimer=setTimeout(()=>{if(token!==adToken||!$('modal').classList.contains('ad-preview'))return;adReady=true;adTimer=null;$('adStatus').textContent='Просмотр завершён. Автосортировка доступна.';$('confirmAutoSort').disabled=false},2000);$('confirmAutoSort').onclick=runAutoSort}
async function runAutoSort(){if(!adReady||state.autoSorting||state.screen!=='work'||state.mode!=='sort'||!state.bag?.length)return;const ids=state.bag.map(x=>x.uid);closeModal();state.autoSorting=true;cancelDrag();renderSortActions();const interval=ids.length>1?700/(ids.length-1):0;try{for(let i=0;i<ids.length;i++){if(i)await new Promise(resolve=>setTimeout(resolve,interval));const item=state.bag?.find(x=>x.uid===ids[i]);if(!item)continue;const node=$('pile').querySelector(`[data-uid="${item.uid}"]`);putItem(item.uid,node?.getBoundingClientRect(),items[item.type].cat,true)}await new Promise(resolve=>setTimeout(resolve,300))}finally{state.autoSorting=false;$('game').classList.remove('auto-sorting');renderWork();updateHud()}}
function createOrder(){if(state.order||!state.stock.length)return;const types=[...new Set(state.stock.map(x=>x.type))].sort(()=>Math.random()-.5).slice(0,3);const recipe=types.map(type=>({type,count:Math.min(rand(1,3),state.stock.filter(x=>x.type===type).length)}));state.order={customer:(state.dayOrders+state.day-1)%customers.length,recipe,packed:[],reward:recipe.reduce((s,r)=>s+r.count*8,20)};}
function beginOrderAssembly(){if(!state.order){toast('Новые поручения появятся после приёмки добычи');return}state.mode='order';state.activeCat=null;setScreen('work')}
function openOrder(){if(state.autoSorting)return;if(!state.order){toast('Новые поручения появятся после приёмки добычи');return}const o=state.order,c=customers[o.customer];if(state.screen!=='reception')setScreen('reception');o.introSeen=true;modal(`<div class="brief-eyebrow">ПОРУЧЕНИЕ ГИЛЬДИИ</div><h2>${c[0]}</h2><p class="brief-intro">${c[1]} просит собрать посылку:</p><div class="brief-list">${o.recipe.map(r=>`<div><img src="${asset(items[r.type].sprite)}" alt=""><span>${items[r.type].name}</span><b>× ${r.count}</b></div>`).join('')}</div><div class="brief-reward"><img src="${asset('s1_19')}" alt="Золото"><span>Награда <b>${o.reward} золотых монет</b></span></div><button class="primary" id="acceptOrder">${o.packed.length?'Продолжить сборку':'Собрать посылку'}</button>`);$('modal').classList.add('order-brief');$('acceptOrder').onclick=()=>{closeModal();beginOrderAssembly()}}
function introduceOrder(){const o=state.order;if(!o)return;setTimeout(()=>{if(state.order===o&&!o.introSeen&&state.screen==='reception'&&!state.paused)openOrder()},900)}
function orderComplete(){return !!state.order&&state.order.recipe.every(r=>state.order.packed.filter(x=>x.type===r.type).length===r.count)}
function finishOrder(){if(!orderComplete()||state.activeCat!==null)return;const n=state.order.reward;state.order=null;state.dayOrders++;state.activeCat=null;pay(n,4);setScreen('reception');toast(`Поручение выполнено! +${n} золота · +4 репутации`);tickArrival();maybeEnd()}
function endDay(){state.ended=true;state.paused=true;const attempts=state.daySorted+state.dayErrors;const accuracy=attempts?Math.round(state.daySorted/attempts*100):100;modal(`<img class="modal-art" src="${asset('s1_7')}" alt=""><h2>День ${state.day} завершён</h2><p>Последний мешок убран, окно закрыто.<br>Завтра город снова принесёт свои находки.</p><div class="summary-grid"><div>Заработано<b>${state.dayGold}</b>золота</div><div>Точность действий<b>${accuracy}%</b>${state.dayErrors} ошибок</div><div>Принято героев<b>${state.dayVisitors}</b>${state.daySorted} предметов разобрано</div><div>Выполнено поручений<b>${state.dayOrders}</b>${state.stock.length} предметов на хранении</div></div><button class="primary" id="nextDay">Открыть склад · день ${state.day+1}</button>`,true);$('nextDay').onclick=nextDay;}
function nextDay(){state.day++;state.seconds=300;state.closing=false;state.ended=false;state.dayGold=state.dayErrors=state.dayVisitors=state.daySorted=state.dayOrders=state.dayBags=0;state.nextArrival=0;closeModal();state.screen='reception';arrive();setScreen('reception')}
function locked(name){modal(`<img class="modal-art" src="${asset(name.includes('Сканер')||name.includes('сканер')?'s10_0':'s10_2')}" alt=""><h2>${name}</h2><p>Пока закрыто.</p><p>Эта возможность появится в следующей версии. Сейчас доступен первый склад: приём добычи, четыре категории и простые поручения.</p><button class="primary" id="okModal">Вернуться на склад</button>`);$('okModal').onclick=closeModal}
function help(){modal(`<h2>Новые правила склада</h2><div class="rules"><b>Сортировка.</b> Передвигайте предметы по столу, собирайте кучки и перетаскивайте в подходящие коробки на полках. Можно нажать на предмет, затем на коробку. После разбора мешка вы остаётесь у стола, пока сами не вернётесь к стойке.<br><br><b>Осмотр.</b> Нажмите на коробку → «Осмотреть»: откроется небольшая коробка. Вещи внутри можно свободно двигать.<br><br><b>Поручение.</b> Посылка слева, чек-лист справа. Подтвердите задание, откройте коробку на полке, раздвигайте вещи и найдите нужное и перетащите в посылку. Красный крестик возвращает коробку на полку.<br><br><b>Выдача.</b> Выполните чек-лист, закройте коробку и нажмите «Выдать посылку».</div><button class="primary" id="okModal">Понятно</button>`);$('okModal').onclick=closeModal}
$('bag').onclick=()=>{state.selectedBag=true;beep('box');renderReception()};$('parcel').onclick=openOrder;$('closeInspector').onclick=closeInspection;$('back').onclick=returnToReception;$('returnToCounter').onclick=returnToReception;$('autoSortButton').onclick=showAutoSortAd;$('ordersNav').onclick=()=>{if(state.bag){toast('Сначала закончите приёмку текущего мешка');return}if(state.order)openOrder();else locked('Новые поручения')};document.querySelectorAll('[data-lock]').forEach(b=>b.onclick=()=>locked(b.dataset.lock));$('help').onclick=help;$('closeModal').onclick=closeModal;$('sound').onclick=()=>{state.muted=!state.muted;beep();updateHud()};$('pause').onclick=()=>{if(state.paused&&!$('modal').classList.contains('hidden'))return;if(!state.started)return;modal('<h2>Склад на паузе</h2><p>Время остановлено. Все предметы на своих местах.</p><button class="primary" id="resume">Продолжить смену</button>');$('resume').onclick=closeModal};addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('modal').classList.contains('hidden'))closeModal();else if(state.inspectCat!==null)closeInspection();else if(state.menuCat!==null){state.menuCat=null;renderBoxMenu()}else if(state.activeCat!==null)returnBox();else if(state.selectedItem!==null){state.selectedItem=null;renderPile()}else if(state.screen==='work')returnToReception()}if(e.code==='Space'&&e.target===document.body){e.preventDefault();$('pause').click()}});
document.addEventListener('visibilitychange',()=>{last=performance.now()});
function tick(now){const dt=Math.min((now-last)/1000,1);last=now;if(state.started&&!state.paused&&!state.autoSorting&&!state.ended&&!document.hidden){state.seconds=Math.max(0,state.seconds-dt);tickArrival();updateHud();if(!state.ended)updateWaitingNotice()}requestAnimationFrame(tick)}render();requestAnimationFrame(tick);
// The agent interface reads the same live state as the visible game.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_warehouse_state',description:'Read the current day, task, loose loot, shelf stock and order without changing the game.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');return {day:state.day,seconds:Math.ceil(state.seconds),screen:state.screen,mode:state.mode,gold:state.gold,activeBox:state.activeCat===null?null:categories[state.activeCat].name,inspectedBox:state.inspectCat===null?null:categories[state.inspectCat].name,loot:(state.bag||[]).map(x=>({id:x.uid,name:items[x.type].name,category:categories[items[x.type].cat].name})),stock:categories.map((c,i)=>({category:c.name,count:totalStock(i)})),order:state.order?{recipe:state.order.recipe.map(r=>({name:items[r.type].name,count:r.count})),packed:state.order.packed.length}:null}}})).catch(()=>{})}catch{}}
